diff --git a/docs/rules/no-spaced-func.md b/docs/rules/no-spaced-func.md
new file mode 100644
index 000000000000..81f908a8e051
--- /dev/null
+++ b/docs/rules/no-spaced-func.md
@@ -0,0 +1,25 @@
+# no spaced func
+
+The no-spaced-func rule does not allow gaps between the function identifier and application.
+
+```js
+fn ()
+```
+
+The following patterns are considered warnings:
+
+```js
+fn ()
+```
+
+```js
+fn
+()
+```
+
+The following patterns are not warnings:
+
+```js
+fn()
+```
+
diff --git a/lib/rules/no-spaced-func.js b/lib/rules/no-spaced-func.js
new file mode 100644
index 000000000000..798f8bdb48a5
--- /dev/null
+++ b/lib/rules/no-spaced-func.js
@@ -0,0 +1,48 @@
+/**
+ * @fileoverview Rule to check that spaced function application
+ * @author Matt DuVall <http://www.mattduvall.com>
+ */
+
+//------------------------------------------------------------------------------
+// Rule Definition
+//------------------------------------------------------------------------------
+
+module.exports = function(context) {
+
+    "use strict";
+
+    function findOpenParen(tokens) {
+        var openParenIndices = [];
+
+        tokens.forEach(function(token, i) {
+            if (token.value === "(") {
+                openParenIndices.push(i);
+            }
+        });
+
+        return openParenIndices;
+    }
+
+    function detectOpenSpaces(node) {
+        var tokens = context.getTokens(node),
+            openParenIndices = findOpenParen(tokens),
+            identifierRange,
+            openParenRange;
+
+        openParenIndices.forEach(function(i) {
+            identifierRange = tokens[i-1].range;
+            openParenRange = tokens[i].range;
+
+            // If theres a gap between the end of the identifier and open paren
+            if (identifierRange[1] !== openParenRange[0]) {
+                context.report(node, "Spaced function application is not allowed.");
+            }
+        });
+    }
+
+    return {
+        "CallExpression": detectOpenSpaces,
+        "NewExpression": detectOpenSpaces
+    };
+
+};
