```js
{
    code: "switch(foo) { case 0: a(); { /* falls through */ } default: b() }",
    errors: errorsDefault
},
{
    code: "switch(foo) { case 0: { /* falls through */ } a(); default: b() }",
    errors: errorsDefault
},
{
    code: "switch(foo) { case 0: if (a) { /* falls through */ } default: b() }",
    errors: errorsDefault
}
```", "Done.", "Done."]

