+                s1_2->s1_4;
+                s1_6->final;
+            }
+            */
+        });
+
+        it("should skip the current branch when 'controller.skip()' was called.", function() {
+            var codePath = parseCodePaths("if (a) { if (b) { foo(); } bar(); } else { out1(); } out2();")[0];
