diff --git a/packages/mui-utils/src/getValidReactChildren.ts b/packages/mui-utils/src/getValidReactChildren.ts
new file mode 100644
index 00000000000000..6a2d5912347563
--- /dev/null
+++ b/packages/mui-utils/src/getValidReactChildren.ts
@@ -0,0 +1,13 @@
+import * as React from 'react';
+
+/**
+ * Gets only the valid children of a component,
+ * and ignores any nullish or falsy child.
+ *
+ * @param children the children
+ */
+export default function getValidReactChildren(children: React.ReactNode) {
+  return React.Children.toArray(children).filter((child) =>
+    React.isValidElement(child),
+  ) as React.ReactElement[];
+}
