+            identifier: 1,
+            target: container,
+            clientX: 42,
+            clientY: 42,
+          }),
+        ],
+      });
+
+      act(() => {
+        clock.tick(100);
+      });
+
+      expect(clickSpy.callCount).to.equal(1);
+    });
+
+    it('should not fire onClick twice on touch tap', () => {
+      const clickSpy = spy();
+      const handleClick = () => act(clickSpy);
+
+      const { getByRole, container } = render(<BottomNavigationAction onClick={handleClick} />);
+
+      fireEvent.touchStart(container.firstChild, {
+        touches: [
+          new Touch({
+            identifier: 1,
+            target: container,
+            clientX: 42,
+            clientY: 42,
+          }),
+        ],
+      });
+
+      fireEvent.touchEnd(container.firstChild, {
+        changedTouches: [
+          new Touch({
+            identifier: 1,
+            target: container,
+            clientX: 42,
+            clientY: 42,
+          }),
+        ],
+      });
+
+      getByRole('button').click();
+
+      act(() => {
+        clock.tick(100);
+      });
+
+      expect(clickSpy.callCount).to.equal(1);
+    });
+
+    it('should not fire onClick if swiping', () => {
+      const clickSpy = spy();
+      const handleClick = () => act(clickSpy);
+
+      const { container } = render(<BottomNavigationAction onClick={handleClick} />);
+
+      fireEvent.touchStart(container.firstChild, {
+        touches: [
+          new Touch({
+            identifier: 1,
+            target: container,
+            clientX: 42,
+            clientY: 42,
+          }),
+        ],
+      });
+
+      fireEvent.touchEnd(container.firstChild, {
+        changedTouches: [
+          new Touch({
+            identifier: 1,
+            target: container,
+            clientX: 84,
+            clientY: 84,
+          }),
+        ],
+      });
+
+      act(() => {
+        clock.tick(100);
+      });
+
+      expect(clickSpy.callCount).to.equal(0);
+    });
+
+    it('should forward onTouchStart and onTouchEnd events', () => {
+      const touchStartSpy = spy();
+      const touchEndSpy = spy();
+      const handleTouchStart = () => act(touchStartSpy);
+      const handleTouchEnd = () => act(touchEndSpy);
+
+      const { container } = render(
+        <BottomNavigationAction onTouchStart={handleTouchStart} onTouchEnd={handleTouchEnd} />,
+      );
+
+      fireEvent.touchStart(container.firstChild, {
+        touches: [
+          new Touch({
+            identifier: 1,
+            target: container,
+            clientX: 42,
+            clientY: 42,
+          }),
+        ],
+      });
+
+      expect(touchStartSpy.callCount).to.be.equals(1);
+
+      fireEvent.touchEnd(container.firstChild, {
+        changedTouches: [
+          new Touch({
+            identifier: 1,
+            target: container,
+            clientX: 84,
+            clientY: 84,
+          }),
+        ],
+      });
+
+      expect(touchEndSpy.callCount).to.be.equals(1);
+    });
+  });
 });

body:
Following up from my comment on issue https://github.com/mui-org/material-ui/issues/15553#issuecomment-497160415 about Typescript components missing style props when wrapping with `withStyles()`.

This adds a new type intersection within the `PropInjector` usage within `withStyles()` to compensate for `React.ComponentProps<C>` removing props used in style functions.

```ts
function withStyles<
    S extends Styles<any, any>,
    Options extends WithStylesOptions<ThemeOfStyles<S>> = {}
>(style: S, options?: Options): PropInjector<
    WithStyles<S, Options['withTheme']>, 
    // Intersect with the Style Props here
    StyledComponentProps<ClassKeyOfStyles<S>> & PropsOfStyles<S>
>;
```

This enables the following

```ts
type StyleProps = { color?: string };
function stylesWithTheme(theme: Theme) {
    return createStyles({
        root: (props: StyleProps) => ({ color: props.color ? props.color : 'yellow' })
    });
}
interface PersonProps extends WithStyles<typeof stylesWithTheme> {
    name: string;
}
function Person(props: PersonProps) {
    return <Typography className={this.props.classes.root}>{this.props.name}</Typography>;
}
function App() {
    // Note use of color attribute
    return <PersonTheme name="Joe Montana" color="green" />;
}
ReactDOM.render(<App />, document.getElementById('root'));
```

Also, I can't determine the file structure to figure out what files to edit. Was `packages/material-ui-styles/src/withStyles/withStyles.d.ts` the correct one or should I have used `packages/material-ui/src/styles/withStyles.d.ts`?

Closes #15553

