issue_description:
I want the submit button to be disabled if the form is in an invalid state. However, the button remains disabled until I clear a field & type again. Below is a code snippet for producing this issue. I am quite new to react, any idea what could be wrong here?

```
function TestForm() {
    const {register, handleSubmit, formState, reset} = useForm({mode: "onChange"});
    const {isValid} = formState;

    useEffect(() => {
        const data = {name: "John", count: 10};
        reset(data);
    }, [reset]);

    return (
        <div>
            <h1>Form state valid: {isValid.toString()}</h1>
            <form onSubmit={handleSubmit(d => console.log(d))}>
                <input type="text" name="name"
                       ref={register({required: true})}/>

                <input type="text" name="count"
                       ref={register({required: true})}/>

                <input type="submit" disabled={!isValid}/>
            </form>
        </div>
    );
}
```
